// Complete normalized procedural body registry for the character model.
// The compressed payload preserves every SVG outline, face metric, and 96-point
// collision ring used to fit the eyes and character-linked effects.
import { gunzipSync } from "node:zlib";

export const BODY_REGISTRY_LAYOUT = Object.freeze({
  payloadSha256: "067b91a28fec44dd50869cb3f656669ae7009f6759a0d607afb4143a167bb7d5",
  shapeCount: 18,
  ringPointsPerShape: 96,
  center: 114.2705,
});

const encoded = "";
const decoded = JSON.parse(gunzipSync(Buffer.from(encoded, "base64")).toString("utf8"));

export const GROK_BODY_SHAPES = Object.freeze(
  Object.fromEntries(
    Object.entries(decoded).map(([id, shape]) => [
      id,
      Object.freeze({
        ...shape,
        face: Object.freeze(shape.face),
        ring: Object.freeze(shape.ring.map((point) => Object.freeze(point))),
      }),
    ]),
  ),
);

if (Object.keys(GROK_BODY_SHAPES).length !== BODY_REGISTRY_LAYOUT.shapeCount) {
  throw new Error("Body-registry payload length mismatch");
}
if (Object.values(GROK_BODY_SHAPES).some((shape) => shape.ring.length !== BODY_REGISTRY_LAYOUT.ringPointsPerShape)) {
  throw new Error("Body-registry ring length mismatch");
}
